'use client';

import { useCallback, useEffect, useState } from 'react';

interface PdfViewerState {
    isLoaded: boolean;
    isLoading: boolean;
    error: string | null;
    Document: any;
    Page: any;
    pdfjs: any;
}

export function usePdfViewer(): PdfViewerState & { initializePdf: () => void } {
    const [state, setState] = useState<PdfViewerState>({
        isLoaded: false,
        isLoading: false,
        error: null,
        Document: null,
        Page: null,
        pdfjs: null,
    });

    const initializePdf = useCallback(async () => {
        // Only run in browser environment
        if (typeof window === 'undefined') return;

        if (state.isLoaded || state.isLoading) return;

        setState(prev => ({ ...prev, isLoading: true, error: null }));

        try {
            // Dynamic import to prevent SSR issues
            const reactPdf = await import('react-pdf');
            const { Document, Page, pdfjs } = reactPdf;

            // Worker resolved by the bundler keeps version in sync with pdfjs-dist
            // and avoids corrupted public/ copies rewritten by Console Ninja in next dev.
            if (typeof window !== 'undefined' && pdfjs.GlobalWorkerOptions) {
                pdfjs.GlobalWorkerOptions.workerSrc = new URL(
                    'pdfjs-dist/build/pdf.worker.min.mjs',
                    import.meta.url,
                ).toString();
            }

            setState({
                isLoaded: true,
                isLoading: false,
                error: null,
                Document,
                Page,
                pdfjs,
            });
        } catch (error) {
            setState({
                isLoaded: false,
                isLoading: false,
                error: error instanceof Error ? error.message : 'Failed to load PDF viewer',
                Document: null,
                Page: null,
                pdfjs: null,
            });
        }
    }, [state.isLoaded, state.isLoading]);

    // Auto-initialize on mount in browser
    useEffect(() => {
        if (typeof window !== 'undefined' && !state.isLoaded && !state.isLoading) {
            initializePdf();
        }
    }, [initializePdf, state.isLoaded, state.isLoading]);

    return {
        ...state,
        initializePdf,
    };
}

